Short answer
- Use an optimistic UI: show messages immediately in the client with a temporary id and a "pending" state, send the message to the server, and return an immediate acknowledgement so the UI stays snappy.
- Persist asynchronously on the backend (publish to a queue / enqueue), process the queue in a worker that saves to MongoDB, then emit a confirmation event to update the message status (confirmed/failed) in all clients.
- Use a client-generated tempId (idempotency key) so the worker can dedupe and the client can match confirmations to pending messages.
- Emit explicit events for pending/confirmed/failed and also support read receipts (messageReceived → mark isRead).
Below is a compact, practical example (server + consumer + client) that follows your stated preference for async persistence and acknowledgement (you preferred that over synchronous blocking in msg 298). Note I mention the earlier “save-before-broadcast” approach (msg 274) — that’s valid, but per your latest preference we use async queuing and optimistic UI instead.

Server (Socket.io) — accept, enqueue and acknowledge quickly
- publishes to RabbitMQ (or a Mongo queue) and immediately replies so the UI isn’t blocked

const io = require('socket.io')(server);
const amqp = require('amqplib'); // RabbitMQ, see msg 245
// helper to publish
async function publishMessageToQueue(channel, queue, msg) {
  await channel.assertQueue(queue, { durable: true });
  channel.sendToQueue(queue, Buffer.from(JSON.stringify(msg)), { persistent: true });
}
io.on('connection', (socket) => {
  socket.on('chatMessage', async (message) => {
    // message: { tempId, text, roomId, senderId, ... }
    const tempId = message.tempId || `t:${Date.now()}`;
    const queuedMsg = { ...message, tempId, receivedAt: Date.now() };
    try {
      // publish to queue quickly (non-blocking in practice)
      await publishMessageToQueue(channel, 'chat-messages', queuedMsg);
      // immediate ack to sender so UI can mark as pending/sent
      socket.emit('messageQueued', { tempId, status: 'pending' });
      // optional tradeoff: broadcast a pending message to room (or only show locally)
      socket.to(message.roomId).emit('newMessage', { ...queuedMsg, isPending: true });
    } catch (err) {
      console.error('Queue publish error:', err);
      socket.emit('messageError', { tempId, error: err.message });
    }
  });
});

Worker / consumer — save to MongoDB, then confirm
- consumes the queue, saves the document, emits confirmation to room, posts analytics webhook if desired

const amqp = require('amqplib');
const mongoose = require('mongoose');
const Message = mongoose.model('Message'); // your schema
async function consume() {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();
  const q = 'chat-messages';
  await ch.assertQueue(q, { durable: true });
  ch.consume(q, async (msg) => {
    const payload = JSON.parse(msg.content.toString());
    try {
      // idempotency: if the message was already saved (same tempId), skip
      const existing = await Message.findOne({ tempId: payload.tempId });
      if (existing) {
        // emit confirmation (in case clients missed it)
        io.to(payload.roomId).emit('messageConfirmed', {
          tempId: payload.tempId,
          id: existing._id,
          timestamp: existing.timestamp,
        });
        ch.ack(msg);
        return;
      }
      const newMessage = new Message({
        text: payload.text,
        senderId: payload.senderId,
        roomId: payload.roomId,
        timestamp: new Date(),
        tempId: payload.tempId,
        isRead: false
      });
      await newMessage.save();
      // notify clients that message is confirmed (replace pending with confirmed)
      io.to(payload.roomId).emit('messageConfirmed', {
        tempId: payload.tempId,
        id: newMessage._id,
        timestamp: newMessage.timestamp,
      });
      // optional: send analytics webhook (post‑MVP) after persistence
      // await sendAnalyticsWebhook(newMessage);
      ch.ack(msg);
    } catch (err) {
      console.error('Worker save error:', err);
      // retry / dead-letter strategies recommended here
      ch.nack(msg, false, false); // send to DLX / dead-letter or implement backoff
    }
  }, { noAck: false });
}
consume().catch(console.error);

Client (React) — optimistic UI + ack handling + retry UI
- create tempId, append to UI immediately, update status on server acks

// send message (client)
function sendMessage(text, roomId) {
  const tempId = `t:${Date.now()}`; // or use uuid()
  const optimisticMsg = { tempId, text, roomId, senderId: me.id, status: 'pending' };
  // show instantly in UI
  setMessages(prev => [...prev, optimisticMsg]);
  // send to server
  socket.emit('chatMessage', optimisticMsg);
}
// socket listeners
socket.on('messageQueued', ({ tempId, status }) => {
  // update UI message status -> pending
  setMessages(prev => prev.map(m => m.tempId === tempId ? { ...m, status } : m));
});
socket.on('messageConfirmed', ({ tempId, id, timestamp }) => {
  // update message: mark confirmed, replace tempId with real id and timestamp
  setMessages(prev => prev.map(m => {
    if (m.tempId === tempId) {
      return { ...m, id, timestamp, status: 'sent', tempId: undefined };
    }
    return m;
  }));
});
socket.on('messageError', ({ tempId, error }) => {
  // mark UI as failed and show retry option
  setMessages(prev => prev.map(m => m.tempId === tempId ? { ...m, status: 'failed', error } : m));
});

