  io.to(roomId).emit('messageConfirmed', { tempId, id: newMessage._id });
} catch (err) {
  console.error('save failed', err);
  // notify clients of permanent failure (or use retries)
  io.to(roomId).emit('messageFailed', { tempId, reason: err.message });
